args.command:
cd /workspace && cp app.db.bak app.db && python3 << 'PYEOF'
import sqlite3, re
conn = sqlite3.connect('app.db')
users = conn.execute("SELECT id, email, full_name FROM users ORDER BY id").fetchall()
email_map = {}
for uid, email, full_name in users:
    if email is None:
        print(f"  uid={uid} email=None -> no_email")
        continue
    norm = email.strip().lower()
    if not norm:
        print(f"  uid={uid} email={email!r} -> blank")
        continue
    if norm in email_map:
        print(f"  uid={uid} email={email!r} norm={norm!r} -> DUP of {email_map[norm]}")
    else:
        email_map[norm] = uid
        print(f"  uid={uid} email={email!r} norm={norm!r} -> keeper")
conn.close()
PYEOF
